package com.github.migmong.dao;

import org.bson.Document;

import com.github.migmong.migration.MigrationEntry;
import com.mongodb.MongoCommandException;
import com.mongodb.client.MongoCollection;
import com.mongodb.client.MongoCursor;
import com.mongodb.client.model.IndexOptions;

/**
 * @author lstolowski
 * @since 10.12.14
 */
public class ChangeEntryIndexDao
{
    /**
     * Name of the unique index which is automatically generated by MongoDB
     * for the keys {changeId: 1, migrationClass: 1}
     */
    private static final String REQUIRED_INDEX_NAME = "changeId_1_migrationClass_1";
    /** MongoDB error code for "namespace not found", e.g. listIndexes on a collection which does not exist yet */
    private static final int NAMESPACE_NOT_FOUND_ERROR_CODE = 26;

    private String migrationCollection;


    public ChangeEntryIndexDao(String migrationCollection)
    {
        this.migrationCollection = migrationCollection;
    }


    /**
     * Creates the required unique index on the migration collection.
     * If an index with the required name already exists:
     * - a unique index is left as is,
     * - a non-unique index is dropped and recreated as unique.
     */
    public void createRequiredUniqueIndex(MongoCollection<Document> collection)
    {
        Document existingIndex = findIndexByName(collection, REQUIRED_INDEX_NAME);

        if (existingIndex == null)
        {
            createUniqueIndex(collection);
        }
        else if (!isUnique(existingIndex))
        {
            dropIndex(collection, existingIndex);
            createUniqueIndex(collection);
        }
    }


    public void dropIndex(MongoCollection<Document> collection, Document index)
    {
        collection.dropIndex(index.get("name").toString());
    }


    public boolean isUnique(Document index)
    {
        Object unique = index.get("unique");
        return (unique != null && unique instanceof Boolean && (Boolean)unique);
    }


    public void setMigrationCollection(String migrationCollection)
    {
        this.migrationCollection = migrationCollection;
    }


    private void createUniqueIndex(MongoCollection<Document> collection)
    {
        collection.createIndex(new Document()
                        .append(MigrationEntry.CHANGE_ID, 1)
                        .append(MigrationEntry.MIGRATION_CLASS, 1),
                new IndexOptions().unique(true));
    }


    private Document findIndexByName(MongoCollection<Document> collection, String indexName)
    {
        try
        {
            try (MongoCursor<Document> indexes = collection.listIndexes().iterator())
            {
                while (indexes.hasNext())
                {
                    Document index = indexes.next();
                    if (indexName.equals(index.get("name")))
                    {
                        return index;
                    }
                }
            }
            return null;
        }
        catch (MongoCommandException e)
        {
            if (e.getErrorCode() == NAMESPACE_NOT_FOUND_ERROR_CODE)
            {
                // the collection does not exist yet, so there is no index
                return null;
            }
            throw e;
        }
    }

}
